public abstract record Payment
{
    private Payment() { }                        // closes the hierarchy
    public sealed record Card(string Number) : Payment;
    public sealed record Transfer(string Iban) : Payment;
}

static string Describe(Payment p) => p switch
{
    Payment.Card c     => c.Number,
    Payment.Transfer t => t.Iban,   // CS8509: hierarchy not provably closed
};
